package com.saurabh.sonicaudiorecorder

import android.app.Application
import android.os.StrictMode
import dagger.hilt.android.HiltAndroidApp

@HiltAndroidApp
class AudioRecorderApp : Application() {
    override fun onCreate() {
        super.onCreate()
        
        // Note: BuildConfig is generated by the build system. 
        // If it's not resolved yet, it will be after the next build.
        setupStrictMode()
    }

    private fun setupStrictMode() {
        // We can use a custom flag or check for debug manually if BuildConfig is giving issues
        // for now we'll assume it will be resolved once the package name change is fully processed by Gradle
        try {
            val debugField = Class.forName("${packageName}.BuildConfig").getField("DEBUG")
            val isDebug = debugField.get(null) as Boolean
            if (isDebug) {
                StrictMode.setThreadPolicy(
                    StrictMode.ThreadPolicy.Builder()
                        .detectDiskReads()
                        .detectDiskWrites()
                        .detectNetwork()
                        .penaltyLog()
                        .build()
                )
                StrictMode.setVmPolicy(
                    StrictMode.VmPolicy.Builder()
                        .detectLeakedSqlLiteObjects()
                        .detectLeakedClosableObjects()
                        .penaltyLog()
                        .build()
                )
            }
        } catch (_: Exception) {
            // Fallback if BuildConfig is not yet available
        }
    }
}
